// ═══════════════════════════════════════════════════════════════════════════
// SEO Export Single — v3.0 | RAPPORT VERTICAL (Screaming Frog style)
// Format : Col A = Rubrique | Col B = Valeur | Col C = Statut/Sévérité
// Toujours ; comme délimiteur (compatible Excel FR/EN)
// ═══════════════════════════════════════════════════════════════════════════

const src  = ($json.body && typeof $json.body === "object") ? $json.body : $json;
const lead = (src.lead  && typeof src.lead  === "object") ? src.lead  : {};
const lang = String(src.language || "fr").toLowerCase().startsWith("fr") ? "fr" : "en";
const FR   = lang === "fr";

// Always semicolon — works in both FR and EN Excel with UTF-8 BOM
const D = ";";

// ── Opportunity selection ───────────────────────────────────────────────────
const opportunityId = String(src.opportunityId || "").trim() || null;
const opps   = Array.isArray(lead.opportunities) ? lead.opportunities : [];
const chosen = opps.find(o => String(o?.id || "") === opportunityId)
  || opps.find(o => String(o?.opportunityStatus || "").toUpperCase() === "PRIMARY")
  || opps[0] || {};

// ── Resolve objects ─────────────────────────────────────────────────────────
const ui       = (chosen?.ui && typeof chosen.ui === "object")   ? chosen.ui
               : (lead?.ui  && typeof lead.ui   === "object")    ? lead.ui : {};
const decision = (lead?.decisionRaw && typeof lead.decisionRaw === "object") ? lead.decisionRaw
               : (lead?.decision    && typeof lead.decision    === "object") ? lead.decision : {};
const signals  = (decision?.signals && typeof decision.signals === "object") ? decision.signals : {};
const tech     = (signals?.techFingerprint && typeof signals.techFingerprint === "object") ? signals.techFingerprint : {};
const analytics = (tech?.analytics && typeof tech.analytics === "object") ? tech.analytics : {};
const cats     = (signals?.categories && typeof signals.categories === "object") ? signals.categories : {};
const T        = signals.technical || {};
const security = T.security || {};

// ── Issues ──────────────────────────────────────────────────────────────────
const rawIssues  = Array.isArray(signals.seoIssues)  ? signals.seoIssues  : [];
const rawPassed  = Array.isArray(signals.seoPassed)  ? signals.seoPassed  : [];
const rawSkipped = Array.isArray(signals.seoSkipped) ? signals.seoSkipped : [];

const criticals = rawIssues.filter(i => typeof i === "object" && i.severity === "critical");
const warnings  = rawIssues.filter(i => typeof i === "object" && i.severity === "warning");
const infos     = rawIssues.filter(i => typeof i === "object" && i.severity === "info");

// ── Analytics tools ─────────────────────────────────────────────────────────
const analyticsTools = [];
if (analytics.hasGTM)      analyticsTools.push("Google Tag Manager");
if (analytics.hasGA4)      analyticsTools.push("Google Analytics 4");
if (analytics.hasGA3)      analyticsTools.push("Universal Analytics (UA)");
if (analytics.hasFBPixel)  analyticsTools.push("Facebook Pixel");
if (analytics.hasHotjar)   analyticsTools.push("Hotjar");
if (analytics.hasHubspot)  analyticsTools.push("HubSpot");
if (analytics.hasMixpanel) analyticsTools.push("Mixpanel");
if (analytics.hasIntercom) analyticsTools.push("Intercom");
if (analytics.hasCrisp)    analyticsTools.push("Crisp");
if (analytics.hasTidio)    analyticsTools.push("Tidio");

// ── Helpers ──────────────────────────────────────────────────────────────────
function esc(val) {
  const s = String(val ?? "");
  const q = s.includes('"') || s.includes("\n") || s.includes("\r") || s.includes(D);
  return q ? `"${s.replace(/"/g, '""')}"` : s;
}
function yes() { return FR ? "✅ Oui" : "✅ Yes"; }
function no()  { return FR ? "❌ Non" : "❌ No";  }
function bool(v) { return v === true ? yes() : no(); }

function catScore(cat) {
  if (!cats[cat]) return "";
  const c = cats[cat];
  const pct = Math.round((c.score / c.max) * 100);
  return `${c.score}/${c.max} (${pct}%)`;
}

function sevIcon(sev) {
  if (sev === "critical") return "🔴 CRITIQUE";
  if (sev === "warning")  return "🟠 ALERTE";
  if (sev === "info")     return "🔵 INFO";
  return sev || "";
}

function scoreColor(score) {
  if (score === null || score === undefined) return "";
  if (score >= 75) return FR ? "✅ BON"     : "✅ GOOD";
  if (score >= 50) return FR ? "🟠 FAIBLE"  : "🟠 WEAK";
  return                       FR ? "🔴 CRITIQUE" : "🔴 CRITICAL";
}

function htmlSizeKb(len) {
  if (!len) return "";
  return `${Math.round(len / 1024 * 10) / 10} Ko`;
}

// ── Row builders ─────────────────────────────────────────────────────────────
const rows = [];

// BOM + title row (makes Excel open UTF-8 correctly)
// BOM is added as the very first character of the CSV string, not as a row

function addTitle(title) {
  rows.push([`═══ ${title.toUpperCase()} ═══`, "", ""].map(esc).join(D));
}

function addSection(label) {
  rows.push(["", "", ""].join(D));  // blank separator
  rows.push([`▶ ${label}`, "", ""].map(esc).join(D));
}

function addRow(label, value, status = "") {
  rows.push([label, value, status].map(esc).join(D));
}

function addBlank() {
  rows.push([" ", "", ""].join(D));
}

function addColHeaders() {
  const A = FR ? "RUBRIQUE"   : "FIELD";
  const B = FR ? "VALEUR"     : "VALUE";
  const C = FR ? "STATUT"     : "STATUS";
  rows.push([A, B, C].map(esc).join(D));
}

// ── Constants ─────────────────────────────────────────────────────────────────
const company   = chosen.company || lead.company || lead.name || "—";
const website   = chosen.website || lead.website || "—";
const rawScore  = typeof signals.rawScore === "number" ? signals.rawScore : null;
const scoreLabel = rawScore !== null ? `${rawScore}/100` : "—";
const dateStr   = new Date().toISOString().slice(0, 10);

// ═══════════════════════════════════════════════════════════════════════════
// BUILD REPORT
// ═══════════════════════════════════════════════════════════════════════════

// ── TITLE ─────────────────────────────────────────────────────────────────
addTitle(FR ? `Rapport SEO — ${company} — ${dateStr}`
            : `SEO Audit Report — ${company} — ${dateStr}`);
addColHeaders();

// ── §1 IDENTIFICATION ──────────────────────────────────────────────────────
addSection(FR ? "§1 · IDENTIFICATION" : "§1 · IDENTIFICATION");
addRow(FR ? "Contact"         : "Contact",          lead.name || "—");
addRow(FR ? "Entreprise"      : "Company",          company);
addRow(FR ? "Profil LinkedIn" : "LinkedIn Profile", lead.profileUrl || "—");
addRow(FR ? "Site web"        : "Website",          website);
addRow(FR ? "Poste détecté"   : "Detected Position", ui.detectedHeadline || decision.detectedHeadline || "—");
addRow(FR ? "Rôle classifié"  : "Classified Role",  ui.role || signals.role || "—");
addRow(FR ? "Source du site"  : "Website Source",   chosen.websiteSource || lead.websiteSource || "—");
addRow(FR ? "Date de capture" : "Capture Date",     lead.createdAt ? new Date(lead.createdAt).toLocaleString(FR ? "fr-FR" : "en-GB") : "—");

// ── §2 DÉCISION COMMERCIALE ────────────────────────────────────────────────
addSection(FR ? "§2 · DÉCISION COMMERCIALE" : "§2 · BUSINESS DECISION");
const leadTypeDisplay = {
  HOT_LEAD:  FR ? "🔥 HOT LEAD"  : "🔥 HOT LEAD",
  WARM_LEAD: FR ? "📬 WARM LEAD" : "📬 WARM LEAD",
  COLD_LEAD: FR ? "❄ COLD LEAD" : "❄ COLD LEAD",
};
addRow(FR ? "Type de lead"      : "Lead Type",   leadTypeDisplay[lead.leadType || decision.leadType || ""] || (lead.leadType || decision.leadType || "—"));
addRow(FR ? "Action recommandée": "Action",       ui.actionLabel || decision.final || "—");
addRow(FR ? "Confiance"         : "Confidence",  ui.confidence || decision.confidence || "—");
addRow(FR ? "Raison"            : "Reason",       ui.reason || decision.reason || "—");
addRow(FR ? "Statut opportunité": "Opp. Status",  chosen.opportunityStatus || "—");
addRow(FR ? "ID opportunité"    : "Opportunity ID", chosen.id || "—");

// ── §3 SEO GLOBAL ──────────────────────────────────────────────────────────
addSection(FR ? "§3 · SEO GLOBAL" : "§3 · SEO OVERVIEW");
addRow(FR ? "Score SEO"           : "SEO Score",       scoreLabel,                                          rawScore !== null ? scoreColor(rawScore) : "");
addRow(FR ? "Niveau SEO"          : "SEO Level",       signals.seoLevel || "—",                             ui.seoEmoji ? `${ui.seoEmoji} ${ui.seoLabel || ""}` : "");
addRow(FR ? "Couverture d'audit"  : "Audit Coverage",  ui.auditCoverageLabel || signals.auditCoverage || "—", ui.auditCoverageColor === "green" ? "✅" : "🟠");
addRow(FR ? "Type de site"        : "Site Type",       ui.siteTypeLabel || signals.siteType || "—");
addRow(FR ? "Type de rendu"       : "Render Type",     tech.renderType || "—");

// ── §4 SCORES PAR CATÉGORIE ────────────────────────────────────────────────
addSection(FR ? "§4 · SCORES PAR CATÉGORIE" : "§4 · CATEGORY SCORES");
addRow(FR ? "Indexabilité"   : "Indexability",  catScore("indexability"), scoreColor(cats.indexability ? Math.round(cats.indexability.score / cats.indexability.max * 100) : null));
addRow(FR ? "On-Page"        : "On-Page",       catScore("onPage"),       scoreColor(cats.onPage       ? Math.round(cats.onPage.score       / cats.onPage.max       * 100) : null));
addRow(FR ? "Technique"      : "Technical",     catScore("technical"),    scoreColor(cats.technical    ? Math.round(cats.technical.score    / cats.technical.max    * 100) : null));
addRow(FR ? "Social & Médias": "Social & Media",catScore("social"),       scoreColor(cats.social       ? Math.round(cats.social.score       / cats.social.max       * 100) : null));

// ── §5 TECH STACK ──────────────────────────────────────────────────────────
addSection(FR ? "§5 · STACK TECHNIQUE" : "§5 · TECH STACK");
addRow("CMS",           tech.cms        || (FR ? "Non détecté" : "Not detected"));
addRow("E-commerce",    tech.ecommerce  || (FR ? "Non détecté" : "Not detected"));
addRow(FR ? "Site builder" : "Site Builder", tech.siteBuilder || (FR ? "Non détecté" : "Not detected"));
addRow("Frameworks",    Array.isArray(tech.frameworks) && tech.frameworks.length > 0 ? tech.frameworks.join(", ") : (FR ? "Non détecté" : "None"));
addRow(FR ? "Serveur"   : "Server",     Array.isArray(tech.serverHints) && tech.serverHints.length > 0 ? tech.serverHints.join(", ") : "—");

// ── §6 ANALYTICS ──────────────────────────────────────────────────────────
addSection(FR ? "§6 · ANALYTICS & TRACKING" : "§6 · ANALYTICS & TRACKING");
addRow(FR ? "Outils détectés" : "Detected Tools",
  analyticsTools.length > 0 ? analyticsTools.join(", ") : (FR ? "Aucun outil détecté" : "No tools detected"),
  analyticsTools.length > 0 ? "✅" : "❌");
addRow("Google Tag Manager",  bool(analytics.hasGTM));
addRow("Google Analytics 4",  bool(analytics.hasGA4));
addRow("Universal Analytics", bool(analytics.hasGA3));
addRow("Facebook Pixel",      bool(analytics.hasFBPixel));
addRow("Hotjar",              bool(analytics.hasHotjar));
addRow("HubSpot",             bool(analytics.hasHubspot));
addRow("Intercom",            bool(analytics.hasIntercom));

// ── §7 ON-PAGE ─────────────────────────────────────────────────────────────
addSection(FR ? "§7 · OPTIMISATION ON-PAGE" : "§7 · ON-PAGE OPTIMIZATION");
addRow(FR ? "Balise <title>"          : "<title> Tag",          bool(T.hasTitle),          T.titleLength ? `${T.titleLength} car.` : "");
addRow(FR ? "Longueur title"          : "Title Length",         T.titleLength !== undefined ? `${T.titleLength} caractères` : "—",
  T.titleLength ? (T.titleLength >= 30 && T.titleLength <= 65 ? "✅ Optimal (30-65)" : T.titleLength < 30 ? "🟠 Trop court" : "🟠 Trop long") : "");
addRow(FR ? "Meta description"        : "Meta Description",     bool(T.hasMetaDescription ?? T.hasMetaDesc));
addRow(FR ? "Longueur meta desc."     : "Meta Desc. Length",    T.metaDescriptionLength !== undefined ? `${T.metaDescriptionLength} caractères` : "—",
  T.metaDescriptionLength ? (T.metaDescriptionLength >= 70 && T.metaDescriptionLength <= 170 ? "✅ Optimal (70-170)" : T.metaDescriptionLength < 70 ? "🟠 Trop courte" : "🟠 Trop longue") : "");
addRow(FR ? "Balises H1"              : "H1 Tags",              T.h1Count !== undefined ? String(T.h1Count) : "—",
  T.h1Count === 1 ? "✅" : T.h1Count === 0 ? "🔴 Absent" : "🟠 Multiple");
addRow(FR ? "Balises H2"              : "H2 Tags",              T.h2Count !== undefined ? String(T.h2Count) : "—");
addRow(FR ? "Balises H3"              : "H3 Tags",              T.h3Count !== undefined ? String(T.h3Count) : "—");
addRow(FR ? "Volume de contenu (est.)" : "Word Count (est.)",   T.estimatedWordCount !== undefined ? `~${T.estimatedWordCount} mots` : "—",
  T.estimatedWordCount ? (T.estimatedWordCount >= 400 ? "✅" : T.estimatedWordCount >= 150 ? "🟠 Léger" : "🔴 Très léger") : "");
addRow(FR ? "Données structurées"     : "Structured Data",      bool(T.hasStructuredData));
addRow(FR ? "Types Schema.org"        : "Schema.org Types",     Array.isArray(T.structuredDataTypes) && T.structuredDataTypes.length > 0 ? T.structuredDataTypes.join(", ") : "—");
addRow("Microdata",                                              bool(T.hasMicrodata));

// ── §8 INDEXABILITÉ ────────────────────────────────────────────────────────
addSection(FR ? "§8 · INDEXABILITÉ & CRAWLABILITÉ" : "§8 · INDEXABILITY & CRAWLABILITY");
addRow(FR ? "Balise canonical"       : "Canonical Tag",      bool(T.hasCanonical));
addRow(FR ? "URL canonical"          : "Canonical URL",      T.canonical || (FR ? "Absente" : "Not set"));
addRow(FR ? "Meta robots: noindex"   : "Meta Robots: noindex", bool(T.hasNoindex), T.hasNoindex ? "🔴 BLOQUE L'INDEXATION" : "✅");
addRow(FR ? "Meta robots: nofollow"  : "Meta Robots: nofollow",bool(T.hasNofollow));
addRow(FR ? "robots.txt présent"     : "robots.txt",         bool(T.robotsPresent));
addRow(FR ? "robots.txt: Disallow /" : "robots.txt: Disallow /", bool(T.robotsDisallowAll), T.robotsDisallowAll ? "🔴 BLOQUE TOUT LE CRAWL" : "✅");
addRow(FR ? "Règles Disallow"        : "Disallow Rules",     T.robotsDisallowRules !== undefined ? String(T.robotsDisallowRules) : "—");
addRow(FR ? "Sitemap référencé dans robots.txt" : "Sitemap in robots.txt", bool(T.robotsHasSitemapRef));
addRow(FR ? "sitemap.xml présent"    : "sitemap.xml",        bool(T.sitemapPresent));
addRow(FR ? "URLs dans le sitemap"   : "Sitemap URL Count",  T.sitemapUrlCount !== undefined ? String(T.sitemapUrlCount) : "—");
addRow(FR ? "Sitemap index"          : "Sitemap Index",      bool(T.sitemapHasIndex));

// ── §9 TECHNIQUE ───────────────────────────────────────────────────────────
addSection(FR ? "§9 · TECHNIQUE & PERFORMANCE" : "§9 · TECHNICAL & PERFORMANCE");
addRow("HTTPS",                bool(security.isHttps ?? T.isHttps), security.isHttps ?? T.isHttps ? "✅ Sécurisé" : "🔴 Non sécurisé — impact SEO critique");
addRow("HSTS",                 bool(security.hasHSTS));
addRow(FR ? "Viewport mobile" : "Mobile Viewport",       bool(T.hasViewport), T.hasViewport ? "✅ Mobile-friendly" : "🔴 Non mobile-friendly");
addRow(FR ? "Taille HTML"     : "HTML Size",             htmlSizeKb(T.htmlLength));
addRow(FR ? "Scripts total"   : "Total Scripts",         T.scriptCount !== undefined ? String(T.scriptCount) : "—");
addRow(FR ? "Scripts render-blocking (<head>)" : "Render-blocking Scripts (<head>)", T.headScriptCount !== undefined ? String(T.headScriptCount) : "—",
  T.headScriptCount !== undefined ? (T.headScriptCount <= 2 ? "✅ Bon" : T.headScriptCount <= 4 ? "🟠 Modéré" : "🔴 Élevé") : "");
addRow(FR ? "Site JS-heavy"   : "JS-heavy Site",         bool(T.isJsHeavy),  T.isJsHeavy ? "🟠 Crawlabilité partielle" : "✅");
addRow("Favicon",              bool(T.hasFavicon));
addRow("Lazy Loading",         bool(T.hasLazyLoading));
addRow("AMP",                  bool(T.hasAmpLink));
addRow(FR ? "Liens internes"  : "Internal Links",        T.internalLinkCount !== undefined ? String(T.internalLinkCount) : "—");
addRow(FR ? "Liens externes"  : "External Links",        T.externalLinkCount !== undefined ? String(T.externalLinkCount) : "—");

// ── §10 SOCIAL & MÉDIAS ────────────────────────────────────────────────────
addSection(FR ? "§10 · SOCIAL & MÉDIAS" : "§10 · SOCIAL & MEDIA");
addRow("og:title",             bool(T.hasOgTitle));
addRow("og:description",       bool(T.hasOgDescription));
addRow(FR ? "og:image (partage social)" : "og:image (social sharing)", bool(T.hasOgImage), T.hasOgImage ? "✅" : "🟠 Partage dégradé");
addRow("Twitter Card",         bool(T.hasTwitterCard), T.twitterCardType ? `Type: ${T.twitterCardType}` : "");
addRow(FR ? "Hreflang (i18n)" : "Hreflang (i18n)",    bool(T.hasHreflang));
addRow(FR ? "Images totales"   : "Total Images",       T.imageCount !== undefined ? String(T.imageCount) : "—");
addRow(FR ? "Images sans alt"  : "Images Missing Alt", T.imageMissingAltCount !== undefined ? String(T.imageMissingAltCount) : "—",
  T.imageCount > 0 ? (T.imageMissingAltCount === 0 ? "✅ Tous les alts renseignés"
    : T.imageMissingAltCount / T.imageCount > 0.5 ? "🔴 Majorité sans alt"
    : "🟠 Quelques alts manquants") : "");

// ── §11 SÉCURITÉ EN-TÊTES ─────────────────────────────────────────────────
addSection(FR ? "§11 · SÉCURITÉ — EN-TÊTES HTTP" : "§11 · SECURITY — HTTP HEADERS");
addRow("Content-Security-Policy",   bool(security.hasCSP));
addRow("X-Frame-Options",           bool(security.hasXFrameOptions));
addRow("X-Content-Type-Options",    bool(security.hasXContentTypeOptions));
addRow("Referrer-Policy",           bool(security.hasReferrerPolicy));

// ── §12 PROBLÈMES DÉTECTÉS ────────────────────────────────────────────────
addSection(FR ? "§12 · PROBLÈMES DÉTECTÉS" : "§12 · DETECTED ISSUES");
addRow(
  FR ? `Résumé (${rawIssues.length} problèmes)` : `Summary (${rawIssues.length} issues)`,
  FR ? `${criticals.length} critiques · ${warnings.length} alertes · ${infos.length} infos`
     : `${criticals.length} critical · ${warnings.length} warnings · ${infos.length} info`
);
addBlank();

if (criticals.length > 0) {
  addRow(FR ? "── Critiques ──" : "── Critical Issues ──", "", "");
  criticals.forEach((i, idx) => {
    addRow(`  ${idx + 1}. ${i.msg || i.key || ""}`, "", "🔴 CRITIQUE");
  });
}
if (warnings.length > 0) {
  addBlank();
  addRow(FR ? "── Alertes ──" : "── Warnings ──", "", "");
  warnings.forEach((i, idx) => {
    addRow(`  ${idx + 1}. ${i.msg || i.key || ""}`, "", "🟠 ALERTE");
  });
}
if (infos.length > 0) {
  addBlank();
  addRow(FR ? "── Informations ──" : "── Info ──", "", "");
  infos.forEach((i, idx) => {
    addRow(`  ${idx + 1}. ${i.msg || i.key || ""}`, "", "🔵 INFO");
  });
}

// ── §13 POINTS POSITIFS ────────────────────────────────────────────────────
addSection(FR ? "§13 · POINTS POSITIFS" : "§13 · PASSED CHECKS");
addRow(
  FR ? `${rawPassed.length} check(s) validé(s)` : `${rawPassed.length} check(s) passed`, "", ""
);
rawPassed.forEach((p, idx) => {
  addRow(`  ${idx + 1}. ${String(p)}`, "", "✅");
});
if (rawSkipped.length > 0) {
  addBlank();
  addRow(FR ? `${rawSkipped.length} check(s) ignoré(s) (rendu client)`
            : `${rawSkipped.length} check(s) skipped (client-side rendering)`, "", "⚪ SKIP");
}

// ── §14 METADATA ──────────────────────────────────────────────────────────
addSection(FR ? "§14 · MÉTADONNÉES DU RAPPORT" : "§14 · REPORT METADATA");
addRow(FR ? "Version export"  : "Export Version", "v3.0");
addRow(FR ? "Version moteur"  : "Engine Version", decision.engine?.version || "v11.0");
addRow(FR ? "Exporté le"      : "Exported At",    new Date().toLocaleString(FR ? "fr-FR" : "en-GB"));
addRow(FR ? "Langue"          : "Language",       FR ? "Français" : "English");
addRow(FR ? "Moteur"          : "Engine",         decision.engine?.name || "n8n_business_engine");
addRow(FR ? "Opportunité ID"  : "Opportunity ID", chosen.id || "—");

// ── Assemble ────────────────────────────────────────────────────────────────
const baseName = company.toLowerCase()
  .replace(/[^a-z0-9]+/g, "_")
  .replace(/^_+|_+$/g, "") || "seo-audit";

// UTF-8 BOM for Excel auto-detection
const BOM = "\uFEFF";
const csv = BOM + rows.join("\r\n");

return [{
  json: {
    ok: true,
    format: "csv",
    mimeType: "text/csv;charset=utf-8",
    filename: `seo-audit_${baseName}_${dateStr}.csv`,
    csv,
    meta: {
      rowCount:    rows.length,
      issueCount:  rawIssues.length,
      passedCount: rawPassed.length,
      language:    lang,
      delimiter:   D,
      generatedAt: new Date().toISOString(),
      exportVersion: "v3.0"
    }
  }
}];
